"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import {
  LayoutDashboard,
  ClipboardList,
  Users,
  Truck,
  FileText,
  Settings,
  MapPin,
  Calculator,
  Calendar,
  TrendingUp,
  DollarSign,
} from "lucide-react";

const navigation = [
  { section: "Operations", items: [
    { name: "Dashboard", href: "/", icon: LayoutDashboard },
    { name: "Orders", href: "/orders", icon: ClipboardList },
    { name: "Calendar", href: "/calendar", icon: Calendar },
    { name: "Crews", href: "/crews", icon: Users },
    { name: "Field Tracking", href: "/field", icon: MapPin },
  ]},
  { section: "Finance", items: [
    { name: "Accounting", href: "/accounting", icon: Calculator },
    { name: "Invoicing", href: "/invoicing", icon: FileText },
    { name: "Expenses", href: "/expenses", icon: DollarSign },
    { name: "Reports", href: "/reports", icon: TrendingUp },
  ]},
  { section: "System", items: [
    { name: "Settings", href: "/settings", icon: Settings },
  ]},
];

export function Sidebar() {
  const pathname = usePathname();

  return (
    <aside className="fixed left-0 top-0 z-40 h-screen w-64 border-r border-slate-200 bg-white overflow-y-auto">
      <div className="flex h-16 items-center gap-2 border-b border-slate-200 px-6">
        <Truck className="h-7 w-7 text-brand-600" />
        <span className="text-lg font-bold text-slate-900">FieldService Pro</span>
      </div>
      <nav className="mt-4 space-y-6 px-3 pb-8">
        {navigation.map((section) => (
          <div key={section.section}>
            <p className="mb-2 px-3 text-xs font-semibold uppercase tracking-wider text-slate-400">
              {section.section}
            </p>
            <div className="space-y-1">
              {section.items.map((item) => {
                const isActive = pathname === item.href;
                return (
                  <Link
                    key={item.name}
                    href={item.href}
                    className={cn(
                      "flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors",
                      isActive
                        ? "bg-brand-50 text-brand-700"
                        : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
                    )}
                  >
                    <item.icon className="h-5 w-5 flex-shrink-0" />
                    {item.name}
                  </Link>
                );
              })}
            </div>
          </div>
        ))}
      </nav>
    </aside>
  );
}

import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { prisma } from "@/lib/prisma";
import { formatCurrency } from "@/lib/utils";
import { TrendingUp, TrendingDown, DollarSign, Receipt } from "lucide-react";

export default async function AccountingPage() {
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const yearStart = new Date(now.getFullYear(), 0, 1);

  const [revenueMTD, revenueYTD, expensesMTD, expensesYTD, recentInvoices, recentExpenses] =
    await Promise.all([
      // Revenue this month
      prisma.invoice.aggregate({
        _sum: { total: true },
        where: { createdAt: { gte: monthStart }, status: { not: "CANCELLED" } },
      }),
      // Revenue this year
      prisma.invoice.aggregate({
        _sum: { total: true },
        where: { createdAt: { gte: yearStart }, status: { not: "CANCELLED" } },
      }),
      // Expenses this month
      prisma.expense.aggregate({
        _sum: { amount: true },
        where: { date: { gte: monthStart } },
      }),
      // Expenses this year
      prisma.expense.aggregate({
        _sum: { amount: true },
        where: { date: { gte: yearStart } },
      }),
      // Recent invoices
      prisma.invoice.findMany({
        take: 5,
        orderBy: { createdAt: "desc" },
        include: { customer: true, payments: true },
      }),
      // Recent expenses
      prisma.expense.findMany({
        take: 5,
        orderBy: { date: "desc" },
        include: { createdBy: true },
      }),
    ]);

  const revMtd = revenueMTD._sum.total ?? 0;
  const expMtd = expensesMTD._sum.amount ?? 0;
  const profitMtd = revMtd - expMtd;
  const revYtd = revenueYTD._sum.total ?? 0;
  const expYtd = expensesYTD._sum.amount ?? 0;
  const profitYtd = revYtd - expYtd;
  const marginMtd = revMtd > 0 ? ((profitMtd / revMtd) * 100) : 0;
  const marginYtd = revYtd > 0 ? ((profitYtd / revYtd) * 100) : 0;

  // Expenses by category
  const expensesByCategory = await prisma.expense.groupBy({
    by: ["category"],
    _sum: { amount: true },
    where: { date: { gte: monthStart } },
  });

  // Outstanding invoices
  const outstanding = await prisma.invoice.aggregate({
    _sum: { total: true },
    where: { status: { in: ["SENT", "OVERDUE"] } },
  });

  // Paid this month
  const paidMtd = await prisma.payment.aggregate({
    _sum: { amount: true },
    where: { receivedAt: { gte: monthStart } },
  });

  const categoryColors: Record<string, string> = {
    MATERIALS: "bg-blue-500",
    LABOR: "bg-green-500",
    FUEL: "bg-amber-500",
    EQUIPMENT: "bg-purple-500",
    SOFTWARE: "bg-cyan-500",
    TRAVEL: "bg-pink-500",
    OTHER: "bg-slate-500",
  };

  const totalExpByCat = expensesByCategory.reduce((s, c) => s + (c._sum.amount ?? 0), 0);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Accounting</h1>
        <p className="mt-1 text-sm text-slate-500">Financial overview and P&L</p>
      </div>

      {/* Top KPI Cards */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className="rounded-lg bg-green-100 p-3">
              <TrendingUp className="h-5 w-5 text-green-600" />
            </div>
            <div>
              <p className="text-sm text-slate-500">Revenue (MTD)</p>
              <p className="text-xl font-bold text-green-700">{formatCurrency(revMtd)}</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className="rounded-lg bg-red-100 p-3">
              <TrendingDown className="h-5 w-5 text-red-600" />
            </div>
            <div>
              <p className="text-sm text-slate-500">Expenses (MTD)</p>
              <p className="text-xl font-bold text-red-700">{formatCurrency(expMtd)}</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className={`rounded-lg p-3 ${profitMtd >= 0 ? "bg-emerald-100" : "bg-red-100"}`}>
              <DollarSign className={`h-5 w-5 ${profitMtd >= 0 ? "text-emerald-600" : "text-red-600"}`} />
            </div>
            <div>
              <p className="text-sm text-slate-500">Net Profit (MTD)</p>
              <p className={`text-xl font-bold ${profitMtd >= 0 ? "text-emerald-700" : "text-red-700"}`}>
                {formatCurrency(profitMtd)}
              </p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className="rounded-lg bg-amber-100 p-3">
              <Receipt className="h-5 w-5 text-amber-600" />
            </div>
            <div>
              <p className="text-sm text-slate-500">Outstanding</p>
              <p className="text-xl font-bold text-amber-700">
                {formatCurrency(outstanding._sum.total ?? 0)}
              </p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* P&L Summary */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <h2 className="text-lg font-semibold text-slate-900">Profit & Loss — This Month</h2>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              <div className="flex justify-between border-b pb-2">
                <span className="text-slate-600">Revenue</span>
                <span className="font-medium text-green-600">{formatCurrency(revMtd)}</span>
              </div>
              <div className="flex justify-between border-b pb-2">
                <span className="text-slate-600">Expenses</span>
                <span className="font-medium text-red-600">({formatCurrency(expMtd)})</span>
              </div>
              <div className="flex justify-between border-b pb-2">
                <span className="font-semibold text-slate-900">Net Profit</span>
                <span className={`font-bold ${profitMtd >= 0 ? "text-emerald-600" : "text-red-600"}`}>
                  {formatCurrency(profitMtd)}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Profit Margin</span>
                <span className={`font-medium ${marginMtd >= 0 ? "text-emerald-600" : "text-red-600"}`}>
                  {marginMtd.toFixed(1)}%
                </span>
              </div>
              {paidMtd._sum.amount != null && (
                <div className="flex justify-between border-t pt-2 text-sm">
                  <span className="text-slate-500">Payments Received</span>
                  <span className="font-medium text-green-600">{formatCurrency(paidMtd._sum.amount)}</span>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* YTD Summary */}
        <Card>
          <CardHeader>
            <h2 className="text-lg font-semibold text-slate-900">Profit & Loss — Year to Date</h2>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              <div className="flex justify-between border-b pb-2">
                <span className="text-slate-600">Revenue</span>
                <span className="font-medium text-green-600">{formatCurrency(revYtd)}</span>
              </div>
              <div className="flex justify-between border-b pb-2">
                <span className="text-slate-600">Expenses</span>
                <span className="font-medium text-red-600">({formatCurrency(expYtd)})</span>
              </div>
              <div className="flex justify-between border-b pb-2">
                <span className="font-semibold text-slate-900">Net Profit</span>
                <span className={`font-bold ${profitYtd >= 0 ? "text-emerald-600" : "text-red-600"}`}>
                  {formatCurrency(profitYtd)}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Profit Margin</span>
                <span className={`font-medium ${marginYtd >= 0 ? "text-emerald-600" : "text-red-600"}`}>
                  {marginYtd.toFixed(1)}%
                </span>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Expenses by Category */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <h2 className="text-lg font-semibold text-slate-900">Expenses by Category (MTD)</h2>
          </CardHeader>
          <CardContent>
            {expensesByCategory.length === 0 ? (
              <p className="text-sm text-slate-500">No expenses this month.</p>
            ) : (
              <div className="space-y-3">
                {expensesByCategory.map((cat) => {
                  const amt = cat._sum.amount ?? 0;
                  const pct = totalExpByCat > 0 ? (amt / totalExpByCat) * 100 : 0;
                  return (
                    <div key={cat.category}>
                      <div className="mb-1 flex justify-between text-sm">
                        <span className="text-slate-600">{cat.category}</span>
                        <span className="font-medium text-slate-900">{formatCurrency(amt)}</span>
                      </div>
                      <div className="h-2 w-full rounded-full bg-slate-100">
                        <div
                          className={`h-2 rounded-full ${categoryColors[cat.category] ?? "bg-slate-500"}`}
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Recent Expenses */}
        <Card>
          <CardHeader>
            <h2 className="text-lg font-semibold text-slate-900">Recent Expenses</h2>
          </CardHeader>
          <CardContent>
            {recentExpenses.length === 0 ? (
              <p className="text-sm text-slate-500">No expenses recorded.</p>
            ) : (
              <div className="space-y-3">
                {recentExpenses.map((exp) => (
                  <div key={exp.id} className="flex items-center justify-between border-b border-slate-100 pb-2 last:border-0 last:pb-0">
                    <div>
                      <p className="text-sm font-medium text-slate-900">{exp.description}</p>
                      <p className="text-xs text-slate-500">
                        {exp.category} — {exp.vendor ?? "—"} — {new Date(exp.date).toLocaleDateString()}
                      </p>
                    </div>
                    <span className="text-sm font-medium text-red-600">{formatCurrency(exp.amount)}</span>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { prisma } from "@/lib/prisma";
import { formatCurrency } from "@/lib/utils";
import { Plus, FileText } from "lucide-react";

export default async function InvoicingPage() {
  const invoices = await prisma.invoice.findMany({
    orderBy: { createdAt: "desc" },
    include: {
      customer: true,
      workOrder: { include: { serviceType: true } },
      payments: true,
    },
  });

  const completedOrders = await prisma.workOrder.findMany({
    where: { status: "COMPLETED", invoice: null },
    include: { customer: true },
  });

  const statusVariant = (status: string) => {
    const map: Record<string, "default" | "success" | "warning" | "danger"> = {
      DRAFT: "default",
      SENT: "warning",
      PAID: "success",
      OVERDUE: "danger",
      CANCELLED: "danger",
    };
    return map[status] ?? "default";
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Invoicing</h1>
          <p className="mt-1 text-sm text-slate-500">
            {invoices.length} invoices — {completedOrders.length} orders ready for invoicing
          </p>
        </div>
        <Button>
          <Plus className="mr-2 h-4 w-4" />
          New Invoice
        </Button>
      </div>

      {/* Orders Ready for Invoicing */}
      {completedOrders.length > 0 && (
        <Card>
          <CardHeader>
            <h2 className="text-lg font-semibold text-slate-900">
              Ready to Invoice ({completedOrders.length})
            </h2>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {completedOrders.map((order) => (
                <div
                  key={order.id}
                  className="flex items-center justify-between rounded-lg border border-slate-200 p-3"
                >
                  <div>
                    <p className="text-sm font-medium text-slate-900">
                      {order.customer.companyName}
                    </p>
                    <p className="text-xs text-slate-500">{order.orderNumber}</p>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className="text-sm font-medium text-slate-900">
                      ${order.price?.toFixed(2) ?? "—"}
                    </span>
                    <Button size="sm">
                      <FileText className="mr-1.5 h-3.5 w-3.5" />
                      Generate Invoice
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Invoice List */}
      <Card>
        <CardHeader>
          <h2 className="text-lg font-semibold text-slate-900">All Invoices</h2>
        </CardHeader>
        <CardContent className="p-0">
          {invoices.length === 0 ? (
            <div className="flex flex-col items-center py-12 text-center">
              <FileText className="mb-3 h-10 w-10 text-slate-300" />
              <p className="text-slate-500">No invoices yet</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-slate-200 bg-slate-50">
                    <th className="px-6 py-3 text-left font-medium text-slate-600">Invoice #</th>
                    <th className="px-6 py-3 text-left font-medium text-slate-600">Customer</th>
                    <th className="px-6 py-3 text-left font-medium text-slate-600">Amount</th>
                    <th className="px-6 py-3 text-left font-medium text-slate-600">Status</th>
                    <th className="px-6 py-3 text-left font-medium text-slate-600">Due Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {invoices.map((invoice) => (
                    <tr key={invoice.id} className="hover:bg-slate-50">
                      <td className="px-6 py-4 font-medium text-brand-700">
                        {invoice.invoiceNumber}
                      </td>
                      <td className="px-6 py-4 text-slate-900">
                        {invoice.customer.companyName}
                      </td>
                      <td className="px-6 py-4 font-medium text-slate-900">
                        {formatCurrency(invoice.total)}
                      </td>
                      <td className="px-6 py-4">
                        <Badge variant={statusVariant(invoice.status)}>
                          {invoice.status}
                        </Badge>
                      </td>
                      <td className="px-6 py-4 text-slate-500">
                        {invoice.dueDate
                          ? new Date(invoice.dueDate).toLocaleDateString()
                          : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatCurrency(amount: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(amount);
}

export function formatDate(date: Date | string): string {
  return new Date(date).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

export function formatDateTime(date: Date | string): string {
  return new Date(date).toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

export const ORDER_STATUSES = [
  "PENDING",
  "DISPATCHED",
  "EN_ROUTE",
  "ON_SITE",
  "COMPLETED",
  "INVOICED",
  "CANCELLED",
] as const;

export type OrderStatus = (typeof ORDER_STATUSES)[number];

export const ORDER_STATUS_COLORS: Record<OrderStatus, string> = {
  PENDING: "bg-yellow-100 text-yellow-800",
  DISPATCHED: "bg-blue-100 text-blue-800",
  EN_ROUTE: "bg-indigo-100 text-indigo-800",
  ON_SITE: "bg-purple-100 text-purple-800",
  COMPLETED: "bg-green-100 text-green-800",
  INVOICED: "bg-gray-100 text-gray-800",
  CANCELLED: "bg-red-100 text-red-800",
};

export const USER_ROLES = [
  "ADMIN",
  "OFFICE_STAFF",
  "CREW_LEAD",
  "CREW_MEMBER",
] as const;

export type UserRole = (typeof USER_ROLES)[number];

import { cn } from "@/lib/utils";

interface CardProps {
  children: React.ReactNode;
  className?: string;
}

export function Card({ children, className }: CardProps) {
  return (
    <div
      className={cn(
        "rounded-xl border border-slate-200 bg-white shadow-sm",
        className
      )}
    >
      {children}
    </div>
  );
}

export function CardHeader({ children, className }: CardProps) {
  return (
    <div className={cn("px-6 py-4 border-b border-slate-200", className)}>
      {children}
    </div>
  );
}

export function CardContent({ children, className }: CardProps) {
  return <div className={cn("px-6 py-4", className)}>{children}</div>;
}

import { cn } from "@/lib/utils";

interface BadgeProps {
  children: React.ReactNode;
  variant?: "default" | "success" | "warning" | "danger" | "info";
  className?: string;
}

const variants = {
  default: "bg-gray-100 text-gray-800",
  success: "bg-green-100 text-green-800",
  warning: "bg-yellow-100 text-yellow-800",
  danger: "bg-red-100 text-red-800",
  info: "bg-blue-100 text-blue-800",
};

export function Badge({ children, variant = "default", className }: BadgeProps) {
  return (
    <span
      className={cn(
        "inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium",
        variants[variant],
        className
      )}
    >
      {children}
    </span>
  );
}

input.content:
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { prisma } from "@/lib/prisma";
import { formatCurrency } from "@/lib/utils";
import { DollarSign, Filter } from "lucide-react";

const EXPENSE_CATEGORIES = [
  "MATERIALS", "LABOR", "FUEL", "EQUIPMENT", "SOFTWARE", "TRAVEL", "OTHER",
] as const;

const categoryColors: Record<string, string> = {
  MATERIALS: "bg-blue-100 text-blue-800",
  LABOR: "bg-green-100 text-green-800",
  FUEL: "bg-amber-100 text-amber-800",
  EQUIPMENT: "bg-purple-100 text-purple-800",
  SOFTWARE: "bg-cyan-100 text-cyan-800",
  TRAVEL: "bg-pink-100 text-pink-800",
  OTHER: "bg-slate-100 text-slate-800",
};

const categoryBarColors: Record<string, string> = {
  MATERIALS: "bg-blue-500",
  LABOR: "bg-green-500",
  FUEL: "bg-amber-500",
  EQUIPMENT: "bg-purple-500",
  SOFTWARE: "bg-cyan-500",
  TRAVEL: "bg-pink-500",
  OTHER: "bg-slate-500",
};

export default async function ExpensesPage() {
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);

  const [expenses, expensesByCategory, totalMtd, totalAllTime] = await Promise.all([
    prisma.expense.findMany({
      orderBy: { date: "desc" },
      include: { createdBy: true, workOrder: { select: { orderNumber: true } } },
    }),
    prisma.expense.groupBy({
      by: ["category"],
      _sum: { amount: true },
      where: { date: { gte: monthStart } },
      orderBy: { _sum: { amount: "desc" } },
    }),
    prisma.expense.aggregate({
      _sum: { amount: true },
      where: { date: { gte: monthStart } },
    }),
    prisma.expense.aggregate({ _sum: { amount: true } }),
  ]);

  const totalCatAmount = expensesByCategory.reduce((s, c) => s + (c._sum.amount ?? 0), 0);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Expenses</h1>
          <p className="mt-1 text-sm text-slate-500">
            Track all business expenses — {expenses.length} total, {formatCurrency(totalMtd._sum.amount ?? 0)} this month
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline">
            <Filter className="mr-2 h-4 w-4" />
            Filter
          </Button>
          <Button>
