import { ChevronLeft, ChevronRight, Clock, MapPin } from "lucide-react";

const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

function getDaysInMonth(year: number, month: number): Date[] {
  const days: Date[] = [];
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);

  // Start from Sunday of the week containing the first
  const start = new Date(firstDay);
  start.setDate(start.getDate() - start.getDay());

  // End on Saturday of the week containing the last
  const end = new Date(lastDay);
  end.setDate(end.getDate() + (6 - end.getDay()));

  const cursor = new Date(start);
  while (cursor <= end) {
    days.push(new Date(cursor));
    cursor.setDate(cursor.getDate() + 1);
  }

  return days;
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function isToday(d: Date): boolean {
  return isSameDay(d, new Date());
}

const priorityBadge = (p: string) => {
  const map: Record<string, "danger" | "warning" | "info" | "default"> = {
    URGENT: "danger",
    HIGH: "warning",
    NORMAL: "info",
    LOW: "default",
  };
  return map[p] ?? "default";
};

export default async function CalendarPage() {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const monthLabel = now.toLocaleString("default", { month: "long", year: "numeric" });

  const monthStart = new Date(year, month, 1);
  const monthEnd = new Date(year, month + 1, 0, 23, 59, 59);

  const days = getDaysInMonth(year, month);

  const workOrders = await prisma.workOrder.findMany({
    where: {
      scheduledDate: { gte: monthStart, lte: monthEnd },
      status: { not: "CANCELLED" },
    },
    include: {
      customer: true,
      property: true,
      crew: { include: { lead: true } },
      serviceType: true,
    },
    orderBy: { scheduledDate: "asc" },
  });

  // Next 7 days upcoming orders
  const weekEnd = new Date();
  weekEnd.setDate(weekEnd.getDate() + 7);
  const upcomingOrders = await prisma.workOrder.findMany({
    where: {
      scheduledDate: { gte: now, lte: weekEnd },
      status: { not: "CANCELLED" },
    },
    include: {
      customer: true,
      property: true,
      crew: { include: { lead: true } },
      serviceType: true,
    },
    orderBy: { scheduledDate: "asc" },
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Calendar</h1>
          <p className="mt-1 text-sm text-slate-500">
            {workOrders.length} orders scheduled this month
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm">
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <span className="text-sm font-medium text-slate-900 min-w-[140px] text-center">
            {monthLabel}
          </span>
          <Button variant="outline" size="sm">
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        {/* Calendar Grid */}
        <div className="lg:col-span-2">
          <Card>
            <CardContent className="p-0">
              {/* Day Headers */}
              <div className="grid grid-cols-7 border-b border-slate-200">
                {DAYS.map((day) => (
                  <div
                    key={day}
                    className="py-2 text-center text-xs font-semibold uppercase text-slate-500"
                  >
                    {day}
                  </div>
                ))}
              </div>
              {/* Day Cells */}
              <div className="grid grid-cols-7">
                {days.map((day, i) => {
                  const dayOrders = workOrders.filter((wo) =>
                    wo.scheduledDate && isSameDay(new Date(wo.scheduledDate), day)
                  );
                  const inMonth = day.getMonth() === month;
                  const today = isToday(day);
                  return (
                    <div
                      key={i}
                      className={`min-h-[90px] border-b border-r border-slate-100 p-1.5 ${
                        !inMonth ? "bg-slate-50/50" : ""
                      } ${today ? "bg-brand-50/30" : ""}`}
                    >
                      <span
                        className={`inline-flex h-6 w-6 items-center justify-center rounded-full text-xs ${
                          today
                            ? "bg-brand-600 font-bold text-white"
                            : inMonth
                            ? "text-slate-900"
                            : "text-slate-400"
                        }`}
                      >
                        {day.getDate()}
                      </span>
                      <div className="mt-0.5 space-y-0.5">
                        {dayOrders.slice(0, 3).map((wo) => (
                          <div
                            key={wo.id}
                            className="truncate rounded bg-brand-100 px-1 py-0.5 text-[10px] font-medium text-brand-800"
                            title={`${wo.customer.companyName} — ${wo.serviceType.name}`}
                          >
                            {wo.customer.companyName}
                          </div>
                        ))}
                        {dayOrders.length > 3 && (
                          <span className="text-[10px] text-slate-400">
                            +{dayOrders.length - 3} more
                          </span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Upcoming Orders Sidebar */}
        <div>
          <Card>
            <CardHeader>
              <h2 className="text-lg font-semibold text-slate-900">Next 7 Days</h2>
            </CardHeader>
            <CardContent className="max-h-[600px] overflow-y-auto">
              {upcomingOrders.length === 0 ? (
                <p className="text-sm text-slate-500">No upcoming orders this week.</p>
              ) : (
                <div className="space-y-3">
                  {upcomingOrders.map((order) => (
                    <div
                      key={order.id}
                      className="rounded-lg border border-slate-200 p-3 hover:border-brand-300 transition-colors"
                    >
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <p className="text-sm font-medium text-slate-900 truncate">
                            {order.customer.companyName}
                          </p>
                          <p className="text-xs text-slate-500">{order.serviceType.name}</p>
                        </div>
                        <Badge variant={priorityBadge(order.priority)}>{order.priority}</Badge>
                      </div>
                      <div className="mt-2 space-y-1">
                        <div className="flex items-center gap-1.5 text-xs text-slate-500">
                          <Clock className="h-3 w-3 flex-shrink-0" />
                          {order.scheduledDate
                            ? new Date(order.scheduledDate).toLocaleDateString("en-US", {
                                weekday: "short",
                                month: "short",
                                day: "numeric",
                              })
                            : "Unscheduled"}
                        </div>
                        <div className="flex items-center gap-1.5 text-xs text-slate-500">
                          <MapPin className="h-3 w-3 flex-shrink-0" />
                          <span className="truncate">
                            {order.property.address}
                          </span>
                        </div>
                      </div>
                      {order.crew && (
                        <div className="mt-2 rounded bg-slate-100 px-2 py-1 text-xs text-slate-600">
                          Crew: {order.crew.name}
                          {order.crew.lead && ` (Lead: ${order.crew.lead.name})`}
                        </div>
                      )}
                      <div className="mt-2">
                        <span
                          className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-medium ${
                            ORDER_STATUS_COLORS[order.status as OrderStatus]
                          }`}
                        >
                          {order.status.replace("_", " ")}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { prisma } from "@/lib/prisma";
import { formatCurrency } from "@/lib/utils";
import { TrendingUp, Users, Building2, Wrench } from "lucide-react";

export default async function ReportsPage() {
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const yearStart = new Date(now.getFullYear(), 0, 1);
  const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);

  // Revenue by customer
  const revenueByCustomer = await prisma.invoice.groupBy({
    by: ["customerId"],
    _sum: { total: true },
    where: { status: { notIn: ["CANCELLED", "DRAFT"] } },
    orderBy: { _sum: { total: "desc" } },
  });

  const customerIds = revenueByCustomer.map((r) => r.customerId);
  const customers = await prisma.customer.findMany({
    where: { id: { in: customerIds } },
  });
  const customerMap = new Map(customers.map((c) => [c.id, c.companyName]));

  // Crew performance (completed orders)
  const crewPerformance = await prisma.crew.findMany({
    include: {
      workOrders: {
        where: {
          status: "COMPLETED",
          completedAt: { gte: yearStart },
        },
        select: { id: true, price: true },
      },
      lead: { select: { name: true } },
    },
    orderBy: { name: "asc" },
  });

  const crewsWithStats = crewPerformance.map((crew) => ({
    name: crew.name,
    lead: crew.lead?.name ?? "Unassigned",
    completed: crew.workOrders.length,
    revenue: crew.workOrders.reduce((s, wo) => s + (wo.price ?? 0), 0),
  }));

  // Service type breakdown
  const serviceBreakdown = await prisma.workOrder.groupBy({
    by: ["serviceTypeId"],
    _count: { id: true },
    where: { status: { not: "CANCELLED" } },
    orderBy: { _count: { id: "desc" } },
  });

  const serviceIds = serviceBreakdown.map((s) => s.serviceTypeId);
  const serviceTypes = await prisma.serviceType.findMany({
    where: { id: { in: serviceIds } },
  });
  const serviceMap = new Map(serviceTypes.map((s) => [s.id, s.name]));

  // Monthly revenue trend (last 12 months)
  const monthlyTrend: { month: string; revenue: number; orders: number }[] = [];
  for (let i = 11; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const endD = new Date(now.getFullYear(), now.getMonth() - i + 1, 0);
    const [rev, count] = await Promise.all([
      prisma.invoice.aggregate({
        _sum: { total: true },
        where: {
          createdAt: { gte: d, lte: endD },
          status: { notIn: ["CANCELLED", "DRAFT"] },
        },
      }),
      prisma.workOrder.count({
        where: {
          createdAt: { gte: d, lte: endD },
          status: { not: "CANCELLED" },
        },
      }),
    ]);
    monthlyTrend.push({
      month: d.toLocaleString("default", { month: "short" }),
      revenue: rev._sum.total ?? 0,
      orders: count,
    });
  }

  // KPI: Total customers, orders MTD, revenue MTD, active crews
  const [totalCustomers, ordersMtd, revenueMtd, activeCrews] = await Promise.all([
    prisma.customer.count(),
    prisma.workOrder.count({ where: { createdAt: { gte: monthStart }, status: { not: "CANCELLED" } } }),
    prisma.invoice.aggregate({
      _sum: { total: true },
      where: { createdAt: { gte: monthStart }, status: { notIn: ["CANCELLED", "DRAFT"] } },
    }),
    prisma.crew.count({ where: { active: true } }),
  ]);

  const maxMonthlyRev = Math.max(...monthlyTrend.map((m) => m.revenue), 1);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Reports</h1>
        <p className="mt-1 text-sm text-slate-500">Business analytics &amp; performance metrics</p>
      </div>

      {/* KPI Row */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className="rounded-lg bg-brand-100 p-3">
              <TrendingUp className="h-5 w-5 text-brand-600" />
            </div>
            <div>
              <p className="text-sm text-slate-500">Revenue (MTD)</p>
              <p className="text-xl font-bold text-slate-900">{formatCurrency(revenueMtd._sum.total ?? 0)}</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className="rounded-lg bg-blue-100 p-3">
              <Wrench className="h-5 w-5 text-blue-600" />
            </div>
            <div>
              <p className="text-sm text-slate-500">Orders (MTD)</p>
              <p className="text-xl font-bold text-slate-900">{ordersMtd}</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className="rounded-lg bg-emerald-100 p-3">
              <Building2 className="h-5 w-5 text-emerald-600" />
            </div>
            <div>
              <p className="text-sm text-slate-500">Customers</p>
              <p className="text-xl font-bold text-slate-900">{totalCustomers}</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 py-5">
            <div className="rounded-lg bg-purple-100 p-3">
              <Users className="h-5 w-5 text-purple-600" />
            </div>
            <div>
              <p className="text-sm text-slate-500">Active Crews</p>
              <p className="text-xl font-bold text-slate-900">{activeCrews}</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Monthly Revenue Trend */}
      <Card>
        <CardHeader>
          <h2 className="text-lg font-semibold text-slate-900">Monthly Revenue Trend</h2>
        </CardHeader>
        <CardContent>
          <div className="flex items-end gap-1.5 h-40">
            {monthlyTrend.map((m, i) => (
              <div key={i} className="flex-1 flex flex-col items-center gap-1">
                <span className="text-[10px] font-medium text-slate-500">
                  {m.revenue > 0 ? formatCurrency(m.revenue).replace(/\.00$/, "") : ""}
                </span>
                <div
                  className="w-full rounded-t bg-brand-500 hover:bg-brand-600 transition-colors"
                  style={{
                    height: `${Math.max((m.revenue / maxMonthlyRev) * 120, 2)}px`,
                  }}
                />
                <span className="text-[10px] text-slate-400">{m.month}</span>
              </div>
            ))}
          </div>
          <div className="mt-2 flex justify-between text-xs text-slate-400">
            <span>Orders: {monthlyTrend.reduce((s, m) => s + m.orders, 0)} last 12 months</span>
            <span>Total: {formatCurrency(monthlyTrend.reduce((s, m) => s + m.revenue, 0))}</span>
          </div>
        </CardContent>
      </Card>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Revenue by Customer */}
        <Card>
          <CardHeader>
            <h2 className="text-lg font-semibold text-slate-900">Revenue by Customer</h2>
          </CardHeader>
          <CardContent>
            {revenueByCustomer.length === 0 ? (
              <p className="text-sm text-slate-500">No invoiced revenue yet.</p>
            ) : (
              <div className="space-y-3">
                {revenueByCustomer.slice(0, 10).map((r) => {
                  const total = r._sum.total ?? 0;
