import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { prisma } from "@/lib/prisma";
import { formatCurrency, formatDate, ORDER_STATUS_COLORS, type OrderStatus } from "@/lib/utils";
import { ClipboardList, FileText, AlertCircle } from "lucide-react";
import Link from "next/link";

const statusVariant = (status: string) => {
  const map: Record<string, "default" | "success" | "warning" | "danger"> = {
    DRAFT: "default", SENT: "warning", PAID: "success", OVERDUE: "danger", CANCELLED: "danger",
  };
  return map[status] ?? "default";
};

export default async function PortalDashboardPage({
  searchParams,
}: {
  searchParams: Promise<{ token?: string }>;
}) {
  const { token } = await searchParams;

  if (!token) {
    return (
      <div className="flex flex-col items-center py-16">
        <AlertCircle className="mb-4 h-12 w-12 text-amber-500" />
        <h2 className="text-xl font-semibold text-slate-900">Access Token Required</h2>
        <p className="mt-2 text-slate-500">Please enter your portal access token to continue.</p>
        <Link
          href="/portal"
          className="mt-4 text-sm font-medium text-brand-600 hover:text-brand-700"
        >
          &larr; Back to sign in
        </Link>
      </div>
    );
  }

  const customer = await prisma.customer.findUnique({
    where: { portalToken: token },
    include: {
      orders: {
        orderBy: { createdAt: "desc" },
        include: { serviceType: true, property: true, crew: { include: { lead: true } } },
      },
      invoices: {
        orderBy: { createdAt: "desc" },
        include: { workOrder: true, payments: true },
      },
    },
  });

  if (!customer) {
    return (
      <div className="flex flex-col items-center py-16">
        <AlertCircle className="mb-4 h-12 w-12 text-red-500" />
        <h2 className="text-xl font-semibold text-slate-900">Invalid Token</h2>
        <p className="mt-2 text-slate-500">The access token you provided is not valid.</p>
        <Link
          href="/portal"
          className="mt-4 text-sm font-medium text-brand-600 hover:text-brand-700"
        >
          &larr; Try again
        </Link>
      </div>
    );
  }

  const totalBilled = customer.invoices
    .filter((inv) => inv.status !== "CANCELLED")
    .reduce((s, inv) => s + inv.total, 0);
  const totalPaid = customer.invoices.reduce(
    (s, inv) => s + inv.payments.reduce((ps, p) => ps + p.amount, 0),
    0
  );
  const outstanding = totalBilled - totalPaid;

  return (
    <div className="space-y-6">
      {/* Welcome Header */}
      <div>
        <p className="text-sm text-slate-500">Welcome back</p>
        <h1 className="text-2xl font-bold text-slate-900">{customer.companyName}</h1>
        {customer.contactName && (
          <p className="text-sm text-slate-500">{customer.contactName}</p>
        )}
      </div>

      {/* Financial Summary */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <Card>
          <CardContent className="py-4">
            <p className="text-sm text-slate-500">Total Billed</p>
            <p className="text-xl font-bold text-slate-900">{formatCurrency(totalBilled)}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="py-4">
            <p className="text-sm text-slate-500">Total Paid</p>
            <p className="text-xl font-bold text-green-600">{formatCurrency(totalPaid)}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="py-4">
            <p className="text-sm text-slate-500">Outstanding</p>
            <p className={`text-xl font-bold ${outstanding > 0 ? "text-amber-600" : "text-green-600"}`}>
              {formatCurrency(outstanding)}
            </p>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Orders */}
        <Card>
          <CardHeader>
            <div className="flex items-center gap-2">
              <ClipboardList className="h-5 w-5 text-brand-600" />
              <h2 className="text-lg font-semibold text-slate-900">Recent Orders</h2>
            </div>
          </CardHeader>
          <CardContent>
            {customer.orders.length === 0 ? (
              <p className="text-sm text-slate-500">No orders yet.</p>
            ) : (
              <div className="space-y-3">
                {customer.orders.slice(0, 10).map((order) => (
                  <div
                    key={order.id}
                    className="rounded-lg border border-slate-200 p-3"
                  >
                    <div className="flex items-start justify-between">
                      <div>
                        <p className="text-sm font-medium text-slate-900">
                          {order.serviceType.name}
                        </p>
                        <p className="text-xs text-slate-500">
                          {order.property.name} &mdash; {order.property.address}
                        </p>
                      </div>
                      <span
                        className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-medium ${
                          ORDER_STATUS_COLORS[order.status as OrderStatus]
                        }`}
                      >
                        {order.status.replace("_", " ")}
                      </span>
                    </div>
                    <div className="mt-2 flex items-center gap-4 text-xs text-slate-500">
                      <span>#{order.orderNumber}</span>
                      {order.scheduledDate && (
                        <span>Scheduled: {formatDate(order.scheduledDate)}</span>
                      )}
                      {order.crew && <span>Crew: {order.crew.name}</span>}
                      {order.price && <span className="font-medium text-slate-700">{formatCurrency(order.price)}</span>}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Invoices */}
        <Card>
          <CardHeader>
            <div className="flex items-center gap-2">
              <FileText className="h-5 w-5 text-brand-600" />
              <h2 className="text-lg font-semibold text-slate-900">Invoices</h2>
            </div>
          </CardHeader>
          <CardContent>
            {customer.invoices.length === 0 ? (
              <p className="text-sm text-slate-500">No invoices yet.</p>
            ) : (
              <div className="space-y-3">
                {customer.invoices.map((invoice) => {
                  const paid = invoice.payments.reduce((s, p) => s + p.amount, 0);
                  const balance = invoice.total - paid;
                  return (
                    <div
                      key={invoice.id}
                      className="rounded-lg border border-slate-200 p-3"
                    >
                      <div className="flex items-start justify-between">
                        <div>
                          <p className="text-sm font-medium text-slate-900">
                            {invoice.invoiceNumber}
                          </p>
                          <p className="text-xs text-slate-500">
                            {invoice.workOrder.serviceType.name} &mdash; {formatDate(invoice.createdAt)}
                          </p>
                        </div>
                        <Badge variant={statusVariant(invoice.status)}>{invoice.status}</Badge>
                      </div>
                      <div className="mt-2 flex items-center justify-between text-sm">
                        <span className="font-medium text-slate-900">{formatCurrency(invoice.total)}</span>
                        {balance > 0 && invoice.status !== "CANCELLED" && (
                          <span className="text-xs text-amber-600">
                            Balance: {formatCurrency(balance)}
                          </span>
                        )}
                        {balance <= 0 && invoice.status === "PAID" && (
                          <span className="text-xs text-green-600">Paid in full</span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { prisma } from "@/lib/prisma";
import { formatCurrency, formatDate } from "@/lib/utils";
import { ArrowLeft, FileText, Download, DollarSign, Printer } from "lucide-react";
import Link from "next/link";
import { notFound } from "next/navigation";

const statusVariant = (status: string) => {
  const map: Record<string, "default" | "success" | "warning" | "danger"> = {
    DRAFT: "default", SENT: "warning", PAID: "success", OVERDUE: "danger", CANCELLED: "danger",
  };
  return map[status] ?? "default";
};

const paymentMethodLabel: Record<string, string> = {
  CASH: "Cash",
  CHECK: "Check",
  CREDIT_CARD: "Credit Card",
  ACH: "ACH Transfer",
  OTHER: "Other",
};

export default async function InvoiceDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const invoice = await prisma.invoice.findUnique({
    where: { id },
    include: {
      customer: true,
      workOrder: {
        include: {
          serviceType: true,
          property: true,
          crew: true,
        },
      },
      items: { orderBy: { createdAt: "asc" } },
      payments: { orderBy: { receivedAt: "desc" } },
    },
  });

  if (!invoice) notFound();

  const totalPaid = invoice.payments.reduce((s, p) => s + p.amount, 0);
  const balance = invoice.total - totalPaid;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Link
            href="/invoicing"
            className="text-slate-400 hover:text-slate-600 transition-colors"
          >
            <ArrowLeft className="h-5 w-5" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">
              Invoice {invoice.invoiceNumber}
            </h1>
            <div className="mt-1 flex items-center gap-2">
              <Badge variant={statusVariant(invoice.status)}>{invoice.status}</Badge>
              {balance > 0 && invoice.status !== "CANCELLED" && (
                <span className="text-sm text-amber-600 font-medium">
                  Balance: {formatCurrency(balance)}
                </span>
              )}
              {balance <= 0 && invoice.status === "PAID" && (
                <span className="text-sm text-green-600 font-medium">Paid in full</span>
              )}
            </div>
          </div>
        </div>
        <div className="flex gap-2">
          <Link href={`/api/invoice/${invoice.id}/pdf`} target="_blank">
            <Button variant="outline">
              <Printer className="mr-2 h-4 w-4" />
              Print PDF
            </Button>
          </Link>
          <Link href={`/api/invoice/${invoice.id}/pdf?download=1`}>
            <Button>
              <Download className="mr-2 h-4 w-4" />
              Download PDF
            </Button>
          </Link>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        {/* Invoice Details */}
        <div className="lg:col-span-2 space-y-6">
          {/* Customer & Order Info */}
          <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
            <Card>
              <CardHeader>
                <h2 className="text-sm font-semibold text-slate-500 uppercase tracking-wider">Bill To</h2>
              </CardHeader>
              <CardContent>
                <p className="font-medium text-slate-900">{invoice.customer.companyName}</p>
                {invoice.customer.contactName && (
                  <p className="text-sm text-slate-600">{invoice.customer.contactName}</p>
                )}
                {invoice.customer.billingAddress && (
                  <p className="mt-1 text-sm text-slate-500 whitespace-pre-wrap">
                    {invoice.customer.billingAddress}
                  </p>
                )}
                {invoice.customer.email && (
                  <p className="text-sm text-slate-500">{invoice.customer.email}</p>
                )}
              </CardContent>
            </Card>
            <Card>
              <CardHeader>
                <h2 className="text-sm font-semibold text-slate-500 uppercase tracking-wider">Order Details</h2>
              </CardHeader>
              <CardContent className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-slate-500">Order #</span>
                  <span className="font-medium text-slate-900">{invoice.workOrder.orderNumber}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Service</span>
                  <span className="font-medium text-slate-900">{invoice.workOrder.serviceType.name}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Property</span>
                  <span className="font-medium text-slate-900 text-right">{invoice.workOrder.property.name}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Address</span>
                  <span className="font-medium text-slate-900 text-right text-xs">{invoice.workOrder.property.address}</span>
                </div>
                {invoice.workOrder.crew && (
                  <div className="flex justify-between">
                    <span className="text-slate-500">Crew</span>
                    <span className="font-medium text-slate-900">{invoice.workOrder.crew.name}</span>
                  </div>
                )}
                {invoice.workOrder.completedAt && (
                  <div className="flex justify-between">
                    <span className="text-slate-500">Completed</span>
                    <span className="font-medium text-slate-900">{formatDate(invoice.workOrder.completedAt)}</span>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>

          {/* Line Items */}
          <Card>
            <CardHeader>
              <h2 className="text-lg font-semibold text-slate-900">Line Items</h2>
            </CardHeader>
            <CardContent className="p-0">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-slate-200 bg-slate-50">
                    <th className="px-6 py-3 text-left font-medium text-slate-600">Description</th>
                    <th className="px-6 py-3 text-right font-medium text-slate-600">Qty</th>
                    <th className="px-6 py-3 text-right font-medium text-slate-600">Unit Price</th>
                    <th className="px-6 py-3 text-right font-medium text-slate-600">Total</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {invoice.items.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-8 text-center text-slate-400">
                        No line items
                      </td>
                    </tr>
                  ) : (
                    invoice.items.map((item) => (
                      <tr key={item.id}>
                        <td className="px-6 py-3 text-slate-900">{item.description}</td>
                        <td className="px-6 py-3 text-right text-slate-600">{item.quantity}</td>
                        <td className="px-6 py-3 text-right text-slate-600">{formatCurrency(item.unitPrice)}</td>
                        <td className="px-6 py-3 text-right font-medium text-slate-900">{formatCurrency(item.total)}</td>
                      </tr>
                    ))
                  )}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 border-slate-200 bg-slate-50">
                    <td colSpan={3} className="px-6 py-3 text-right text-sm text-slate-600">Subtotal</td>
                    <td className="px-6 py-3 text-right font-medium text-slate-900">{formatCurrency(invoice.subtotal)}</td>
                  </tr>
                  <tr className="bg-slate-50">
                    <td colSpan={3} className="px-6 py-3 text-right text-sm text-slate-600">
                      Tax ({invoice.taxRate}%)
                    </td>
                    <td className="px-6 py-3 text-right font-medium text-slate-900">{formatCurrency(invoice.taxAmount)}</td>
                  </tr>
                  <tr className="bg-slate-50">
                    <td colSpan={3} className="px-6 py-3 text-right text-sm font-semibold text-slate-900">Total</td>
                    <td className="px-6 py-3 text-right text-lg font-bold text-slate-900">{formatCurrency(invoice.total)}</td>
                  </tr>
                </tfoot>
              </table>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Payment Summary */}
          <Card>
            <CardHeader>
              <h2 className="text-lg font-semibold text-slate-900">Payment Summary</h2>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Invoice Total</span>
                <span className="font-medium text-slate-900">{formatCurrency(invoice.total)}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Amount Paid</span>
                <span className="font-medium text-green-600">{formatCurrency(totalPaid)}</span>
              </div>
              <div className="flex justify-between border-t pt-2 text-sm">
                <span className="font-semibold text-slate-900">Balance</span>
                <span className={`font-bold ${balance > 0 ? "text-amber-600" : "text-green-600"}`}>
                  {formatCurrency(balance)}
                </span>
              </div>
              {invoice.dueDate && (
                <div className="flex justify-between text-sm border-t pt-2">
                  <span className="text-slate-500">Due Date</span>
                  <span className="font-medium text-slate-900">{formatDate(invoice.dueDate)}</span>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Recorded Payments */}
          <Card>
            <CardHeader>
              <h2 className="text-lg font-semibold text-slate-900">Payments</h2>
            </CardHeader>
            <CardContent>
              {invoice.payments.length === 0 ? (
                <div className="flex flex-col items-center py-6 text-center">
                  <DollarSign className="mb-2 h-8 w-8 text-slate-300" />
                  <p className="text-sm text-slate-500">No payments recorded</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {invoice.payments.map((payment) => (
                    <div
                      key={payment.id}
                      className="rounded-lg border border-slate-200 p-3"
                    >
                      <div className="flex items-center justify-between">
                        <span className="font-medium text-green-600">{formatCurrency(payment.amount)}</span>
                        <Badge variant="info">{paymentMethodLabel[payment.method] ?? payment.method}</Badge>
                      </div>
                      <div className="mt-1 text-xs text-slate-500">
                        {formatDate(payment.receivedAt)}
                        {payment.reference && ` — Ref: ${payment.reference}`}
                      </div>
                      {payment.notes && (
                        <p className="mt-1 text-xs text-slate-500">{payment.notes}</p>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Notes */}
          {invoice.notes && (
            <Card>
              <CardHeader>
                <h2 className="text-lg font-semibold text-slate-900">Notes</h2>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-slate-600 whitespace-pre-wrap">{invoice.notes}</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

import { prisma } from "@/lib/prisma";
import { NextRequest, NextResponse } from "next/server";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const invoice = await prisma.invoice.findUnique({
    where: { id },
    include: {
      customer: true,
      workOrder: { include: { serviceType: true, property: true } },
      items: true,
      payments: true,
    },
  });

  if (!invoice) {
    return NextResponse.json({ error: "Invoice not found" }, { status: 404 });
  }

  const totalPaid = invoice.payments.reduce((s, p) => s + p.amount, 0);
  const fmt = (n: number) => `$${n.toFixed(2)}`;
  const dfmt = (d: Date | string) => new Date(d).toLocaleDateString("en-US", {
    year: "numeric", month: "long", day: "numeric",
  });

  const lineItemsHtml = invoice.items.length > 0
    ? invoice.items
        .map(
          (item) => `
        <tr>
          <td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;">${item.description}</td>
          <td style="padding:8px 12px;text-align:right;border-bottom:1px solid #e2e8f0;">${item.quantity}</td>
          <td style="padding:8px 12px;text-align:right;border-bottom:1px solid #e2e8f0;">${fmt(item.unitPrice)}</td>
          <td style="padding:8px 12px;text-align:right;border-bottom:1px solid #e2e8f0;">${fmt(item.total)}</td>
        </tr>`
        )
        .join("")
    : `<tr><td colspan="4" style="padding:8px 12px;text-align:center;color:#94a3b8;">No line items</td></tr>`;

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Invoice ${invoice.invoiceNumber}</title>
  <style>
    * { margin:0; padding:0; box-sizing:border-box; }
    body { font-family: system-ui, -apple-system, sans-serif; color:#1e293b; padding:48px 56px; font-size:13px; line-height:1.5; }
    .header { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:40px; }
    .header h1 { font-size:28px; font-weight:800; color:#0f172a; }
    .header .badge { display:inline-block; padding:4px 12px; border-radius:9999px; font-size:12px; font-weight:600; }
    .badge-paid { background:#dcfce7; color:#166534; }
    .badge-sent { background:#fef9c3; color:#854d0e; }
    .badge-overdue { background:#fee2e2; color:#991b1b; }
    .badge-draft { background:#f1f5f9; color:#475569; }
    .badge-cancelled { background:#fee2e2; color:#991b1b; }
